cat > src/__tmp_theme.test.tsx <<'EOF'
import { renderToString } from 'react-dom/server';
import { expect, test } from 'vitest';
const store: Record<string, string> = {};
(globalThis as any).window = Object.assign(globalThis, {
  localStorage: { getItem: (k: string) => store[k] ?? null, setItem: (k: string, v: string) => { store[k] = v; } },
  matchMedia: () => ({ matches: false, addEventListener() {}, removeEventListener() {} }),
});
test('restores stored theme', async () => {
  const { PersistentThemeProvider, readStoredTheme } = await import('./theme');
  const { App } = await import('./App');
  expect(readStoredTheme()).toBe('light');
  store['app-theme'] = 'garbage';
  expect(readStoredTheme()).toBe('light');
  store['app-theme'] = 'dark';
  const html = renderToString(<PersistentThemeProvider><App /></PersistentThemeProvider>);
  expect(html).toMatch(/value="dark"[^>]*checked|checked[^>]*value="dark"/);
});
EOF
npx vitest run src/__tmp_theme.test.tsx 2>&1 | tail -12; rm src/__tmp_theme.test.tsx; git status --short

